		private Guid GetIdentifierGuid(string identifier)
		{
			Guid id = default(Guid);
			if (!String.IsNullOrEmpty(identifier))
			{
				id = Guid.Parse(identifier);
			}
			else
			{
				id = Guid.NewGuid();
			}

			return id;
		}
	}
